FILE: app/src/orbit-camera.ts
```ts
import {
  createArcRotateCamera,
  attachControl,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });
  enableArcRotateKeyboardControls();
  attachControl(camera, canvas, scene, { keyboard: true });
  return camera;
}
```

I created `src/orbit-camera.ts` which builds an `ArcRotateCamera` at radius 10 targeting the origin, calls `enableArcRotateKeyboardControls()` (required before `attachControl` will honour `keyboard: true`, per note 9), then attaches the standard pointer and keyboard controls to the canvas. The only thing I was slightly unsure of is whether `enableArcRotateKeyboardControls()` must also be called before `createArcRotateCamera` — the notes only state it must precede `attachControl`, so I placed it right before that call.
